'use strict'

import resource from '../../resource'
import { NES_PIXEL, TILE_WIDTH, LINK_DIRECTION_NORTH, LINK_DIRECTION_WEST } from '../../constant'
import { Enemy, STATE_WAITING, drawImage } from './common'
import { isInRoom } from '../room-box'

// The hand out of the walls, read in the ROM (object $27, bank 4 $90E4). It waits in the wall until Link goes along
// one: against the west or east wall (x = $20 or $D0, y from $6D to $B4) or the north or south one (y = $5D or $BD,
// x from $29 to $C7), one at most every 96 frames ($29). It comes out 36 NES pixels from Link along the wall (50
// when he walks), on the side he does not face, and goes 7 tiles of a path (table $90A0: 2 out of the wall, 3
// towards Link, 2 back in) at $18 (0.375 NES pixel a frame), then waits again. Touching Link, it takes half a
// heart and carries him off: at the end of its path, the level starts again at its entrance
const WALLMASTER = { life: 2, contactDamage: 0.5 }
const SPEED = 0x18
const PER_PIXEL = 0x40
const TILES = 7
export const WALLMASTER_STEPS = 0x60
const NEAR = 0x24
const NEAR_WALKING = 0x32
// The 8 paths, 8 tiles each: way in the low digit (1 right, 2 left, 4 down, 8 up), the image flipped by the high
// one ($40 across, $80 upside down). By the west wall (from below Link, from above), the east one, the north one
// (from his right, from his left) and the south one
const PATHS = [
  0x01, 0x01, 0x08, 0x08, 0x08, 0x02, 0x02, 0x02, 0xc1, 0xc1, 0xc4, 0xc4, 0xc4, 0xc2, 0xc2, 0xc2,
  0x42, 0x42, 0x48, 0x48, 0x48, 0x41, 0x41, 0x41, 0x82, 0x82, 0x84, 0x84, 0x84, 0x81, 0x81, 0x81,
  0xc4, 0xc4, 0xc2, 0xc2, 0xc2, 0xc8, 0xc8, 0xc8, 0x84, 0x84, 0x81, 0x81, 0x81, 0x88, 0x88, 0x88,
  0x48, 0x48, 0x42, 0x42, 0x42, 0x44, 0x44, 0x44, 0x08, 0x08, 0x01, 0x01, 0x01, 0x04, 0x04, 0x04
]
const WAYS = { 1: [1, 0], 2: [-1, 0], 4: [0, 1], 8: [0, -1] }
const NES_TOP = 0x3d
const STATE_COMING = 'coming'

// Link's place in NES pixels on the screen
const nesX = (map, link) => (link.x - map.x) / NES_PIXEL
const nesY = (map, link) => (link.y - map.y) / NES_PIXEL + NES_TOP

// One step of the wait between two hands of the room
export function tickWallmasters (map) {
  if (map.wallmasterSteps > 0) {
    map.wallmasterSteps--
  }
}

export class Wallmaster extends Enemy {
  constructor (type, x, y, random = Math.random) {
    super(type, x, y, WALLMASTER, random)
    this.setState(STATE_WAITING)
    this.path = 0
    this.tiles = 0
    this.moved = 0
    this.fraction = 0
    this.holding = false
  }

  // Coming out of the wall, if Link is along one; true if it did
  comeOut (map, link) {
    const x = nesX(map, link)
    const y = nesY(map, link)
    if ((x < 0x29 || x >= 0xc8) && (y < 0x6d || y >= 0xb5)) {
      return false
    }
    const near = link.moving ? NEAR_WALKING : NEAR
    let path
    let place
    if (x === 0x20 || x === 0xd0) {
      path = x === 0x20 ? 0 : 16
      const ahead = link.direction === LINK_DIRECTION_NORTH
      path += ahead ? 8 : 0
      place = [x === 0x20 ? 0 : 0xf0, y + (ahead ? -near : near)]
    } else if (y === 0x5d || y === 0xbd) {
      path = y === 0x5d ? 32 : 48
      const ahead = link.direction === LINK_DIRECTION_WEST
      path += ahead ? 8 : 0
      place = [x + (ahead ? -near : near), y === 0x5d ? NES_TOP : 0xdd]
    } else {
      return false
    }
    this.x = map.x + place[0] * NES_PIXEL
    this.y = map.y + (place[1] - NES_TOP) * NES_PIXEL
    this.path = path
    this.tiles = 0
    this.moved = 0
    this.fraction = 0
    this.inRoom = false
    this.nesX = place[0]
    this.setState(STATE_COMING)
    map.wallmasterSteps = WALLMASTER_STEPS
    return true
  }

  get way () {
    return PATHS[this.path + this.tiles]
  }

  // Hit only once out of the wall (measured: no damage while x < $20)
  get isVulnerable () {
    return super.isVulnerable && this.inRoom
  }

  act (map, link) {
    if (this.state === STATE_WAITING) {
      if (!map.wallmasterSteps && !map.wallmasterHolding) {
        this.comeOut(map, link)
      }
      return
    }
    this.fraction += SPEED
    const pixels = Math.floor(this.fraction / PER_PIXEL)
    this.fraction %= PER_PIXEL
    const [dx, dy] = WAYS[this.way & 0x0f]
    for (let i = 0; i < pixels; i++) {
      this.x += dx * NES_PIXEL
      this.y += dy * NES_PIXEL
      this.moved += NES_PIXEL
      if (this.moved >= TILE_WIDTH) {
        this.moved = 0
        this.tiles++
        if (this.tiles >= TILES) {
          this.end(map)
          return
        }
      }
    }
    if (this.holding) {
      link.x = this.x
      link.y = this.y
    }
    this.inRoom = isInRoom(map, this.x, this.y)
    this.nesX = (this.x - map.x) / NES_PIXEL
  }

  // Back in the wall; with Link, the level starts again (see Game)
  end (map) {
    this.setState(STATE_WAITING)
    if (this.holding) {
      map.wallmasterHolding = false
      map.carriedOff = true
    }
  }

  // Touching Link: half a heart, and it carries him off
  fight (map, link) {
    const hurt = !this.holding && this.isActive && !map.frozen && link.invincibleSteps === 0
    super.fight(map, link)
    if (hurt && link.invincibleSteps > 0 && !map.wallmasterHolding) {
      this.holding = true
      map.wallmasterHolding = true
      link.knockback = undefined
      link.grabbed = this
    }
  }

  // Each half of the hand (8 NES pixels) goes behind the scenery in the west and east walls (bank 4, $929E: bit 5 of
  // its attribute when its x is under $18 or its right edge from $E9; measured, nothing of it shows through the
  // walls). Over the north and south walls it is drawn in front, as in the ROM
  drawBody (context) {
    if (this.state === STATE_WAITING) {
      return
    }
    const half = this.width / 2
    const shown = [0, 1].filter(k => {
      const x = this.nesX + k * 8
      return x >= 0x18 && x + 8 < 0xe9
    })
    if (shown.length === 0) {
      return
    }
    const way = this.way ?? 0
    const sprite = resource.getSprite('wallmaster_move')
    const frame = Math.floor(this.tiles + this.moved / TILE_WIDTH * 2) % 2
    context.save()
    if (shown.length === 1) {
      context.beginPath()
      context.rect(this.x + shown[0] * half, this.y, half, this.height)
      context.clip()
    }
    context.translate(this.x + this.width / 2, this.y + this.height / 2)
    // The sprite (wallmaster_move) is the image of the ROM flipped both ways: drawn flipped back, it is the hand
    // without flips ($01; measured: by the west wall, coming from below Link, the dots of the palm bottom left)
    context.scale(way & 0x40 ? 1 : -1, way & 0x80 ? 1 : -1)
    drawImage(context, sprite, frame, -this.width / 2, -this.height / 2, this.width, this.height)
    context.restore()
  }
}
