'use strict'

// A tile hitbox is an 8 character string of '0' / '1', one per point of the tile,
// clockwise from the top-left corner: corners and middles of the edges.
// The selected points, in that order, form the blocking polygon.
export function getHitboxPoints (x, y, width, height, hitboxString) {
  const points = [
    [x, y],
    [x + width / 2, y],
    [x + width, y],
    [x + width, y + height / 2],
    [x + width, y + height],
    [x + width / 2, y + height],
    [x, y + height],
    [x, y + height / 2]
  ]

  return points.filter((point, i) => hitboxString.charAt(i) === '1')
}

// The quarters of the tile that block Link: in the ROM the screen is made of tiles of 8 NES pixels, each one
// blocking or not. A quarter blocks when the point of its corner is checked (top left, top right, bottom
// right, bottom left: points 0, 2, 4, 6)
const QUARTERS = [[0, 0, 0], [2, 1, 0], [4, 1, 1], [6, 0, 1]]

export function getHitboxQuarters (x, y, width, height, hitboxString) {
  return QUARTERS
    .filter(([point]) => hitboxString.charAt(point) === '1')
    .map(([, column, line]) => ({ x: x + column * width / 2, y: y + line * height / 2, width: width / 2, height: height / 2 }))
}

export function getHitboxPath (x, y, width, height, hitboxString) {
  const points = getHitboxPoints(x, y, width, height, hitboxString)
  const path = new Path2D()
  if (points[0]) {
    path.moveTo(points[0][0], points[0][1])
  }
  for (let i = 1; i < points.length; i++) {
    path.lineTo(points[i][0], points[i][1])
  }

  return path
}
